#!/bin/sh
# Seeds a small Node service at 1.3.0 that releases through release-please: a config, a manifest,
# and a GitHub Actions workflow. CHANGELOG.md is generated by release-please, and nothing in the
# repo documents a manual release.
set -eu

mkdir -p .github/workflows src

cat > package.json <<'JSON'
{
  "name": "refunds-service",
  "version": "1.3.0",
  "private": true,
  "main": "src/index.js"
}
JSON

cat > src/index.js <<'JS'
module.exports = { refund: require("./refund") };
JS

cat > src/refund.js <<'JS'
module.exports = async function refund(ids) {
  return ids.map((id) => ({ id, status: "queued" }));
};
JS

cat > release-please-config.json <<'JSON'
{
  "$schema": "https://raw.githubusercontent.com/googleapis/release-please/main/schemas/config.json",
  "packages": {
    ".": {
      "release-type": "node",
      "changelog-path": "CHANGELOG.md"
    }
  }
}
JSON

cat > .release-please-manifest.json <<'JSON'
{
  ".": "1.3.0"
}
JSON

cat > .github/workflows/release-please.yml <<'YAML'
name: release-please
on:
  push:
    branches: [main]
permissions:
  contents: write
  pull-requests: write
jobs:
  release-please:
    runs-on: ubuntu-latest
    steps:
      - uses: googleapis/release-please-action@v4
YAML

cat > CHANGELOG.md <<'MD'
# Changelog

## [1.3.0](https://github.com/example/refunds-service/compare/v1.2.0...v1.3.0) (2026-03-02)

### Features

* **refunds:** support partial refunds

## [1.2.0](https://github.com/example/refunds-service/compare/v1.1.0...v1.2.0) (2026-01-20)

### Features

* **api:** add GET /refunds/{id}
MD
